parameters.query:
select supplier_code, lower(billing_email) as billing_email
from ref.suppliers
where status = 'approved';

parameters.jsCode:
const crypto = require('crypto');

// Supplier reference list. Comes from the parallel branch, resolved by node name.
const suppliers = $('Load suppliers').all();

if (suppliers.length === 0) {
  throw new Error(
    'Supplier list is empty. Check the Load suppliers node: ' +
    'it must sit above on the canvas so it runs first.'
  );
}

const byEmail = new Map();
for (const s of suppliers) {
  if (!s.json.billing_email || !s.json.supplier_code) {
    throw new Error('Supplier list contains a row without email or supplier code.');
  }
  byEmail.set(s.json.billing_email.toLowerCase(), s.json.supplier_code);
}

const out = [];
const mails = $input.all();

for (let i = 0; i < mails.length; i++) {
  const mail = mails[i].json;
  const binary = mails[i].binary || {};
  const sender = mail.from?.value?.[0]?.address?.toLowerCase() ?? null;
  const receivedAt = mail.date ?? null;

  // Sender is a property of the mail, not of the attachment. Resolved once,
  // before the attachment loop, so that mails with no PDF still carry a
  // definite true/false. A null here would mean "unknown" in SQL, and
  // `where sender_approved = false` would silently skip such mails.
  const supplier = sender ? (byEmail.get(sender) ?? null) : null;
  const senderApproved = supplier !== null;

  // First pass: count attachments and record what gets skipped.
  // Metadata only — the binary buffer is expensive and not needed here.
  const pdfProps = [];
  const skipped = [];
  for (const prop of Object.keys(binary)) {
    const meta = binary[prop];
    if (meta.mimeType === 'application/pdf') {
      pdfProps.push(prop);
    } else {
      skipped.push(`${meta.fileName ?? 'unnamed'} (${meta.mimeType ?? 'unknown'})`);
    }
  }

  const attachmentCount = Object.keys(binary).length;
  const pdfCount = pdfProps.length;

  // Mail-level fields ride on every item, both the ones carrying a PDF and
  // the single placeholder for mails without one. Save document and Save mail
  // both call doc.record_mail with these.
  const mailFields = {
    message_id: mail.messageId ?? null,
    sender: sender,
    subject: mail.subject ?? null,
    received_at: receivedAt,
    sender_approved: senderApproved,
    attachment_count: attachmentCount,
    pdf_count: pdfCount,
    skipped_files: skipped.length ? skipped.join('; ') : null,
  };

  // Nothing usable in this mail. Emit one item so the mail leaves a trace.
  // Before 30 August this loop simply produced nothing and the mail vanished.
  if (pdfCount === 0) {
    out.push({
      json: {
        ...mailFields,
        has_pdf: false,
        mail_status: attachmentCount === 0 ? 'no_attachment' : 'no_pdf',
        supplier_code: supplier,
      },
      pairedItem: i,
    });
    continue;
  }

  // Second pass: hash each PDF and build its storage path.
  for (const prop of pdfProps) {
    const meta = binary[prop];
    const buf = await this.helpers.getBinaryDataBuffer(i, prop);
    const sha = crypto.createHash('sha256').update(buf).digest('hex');

    // Storage layout: raw/{supplier}/{yyyy}/{mm}/{sha256}.pdf
    // Unknown senders go to _unknown so the path never has an empty segment.
    const folder = supplier ?? '_unknown';
    const yyyy = receivedAt ? receivedAt.slice(0, 4) : 'unknown';
    const mm = receivedAt ? receivedAt.slice(5, 7) : 'unknown';

    out.push({
      json: {
        ...mailFields,
        has_pdf: true,
        mail_status: 'ingested',
        file_name: meta.fileName,
        file_sha256: sha,
        file_size: buf.length,
        supplier_code: supplier,
        storage_path: `raw/${folder}/${yyyy}/${mm}/${sha}.pdf`,
      },
      binary: { data: meta },
      pairedItem: i,
    });
  }
}

return out;
